<?php
ob_start();
$pageTitle='Checkout'; require_once __DIR__.'/../includes/header.php';
if(!isLoggedIn()){setFlash('info','Masuk terlebih dahulu untuk melanjutkan checkout.');redirect(BASE_URL.'/auth/login.php');}
$_SESSION['cart']=$_SESSION['cart']??[];$all=$conn?[]:getDummyProducts();
if($conn){$ids=array_map('intval',array_keys($_SESSION['cart']));if($ids){$r=$conn->query('SELECT * FROM products WHERE id IN ('.implode(',',$ids).') AND status="available" AND stock>0');while($r&&$p=$r->fetch_assoc())$all[]=$p;}}
$items=[];$total=0;foreach($all as $p)if(isset($_SESSION['cart'][$p['id']])){$qty=min((int)$_SESSION['cart'][$p['id']],(int)$p['stock']);if($qty){$p['quantity']=$qty;$p['subtotal']=$qty*$p['price'];$items[]=$p;$total+=$p['subtotal'];}}
if(!$items){setFlash('info','Keranjang masih kosong.');redirect(BASE_URL.'/buyer/cart.php');}
$error='';$address='';$phone='';$payment='Transfer Bank';
if($_SERVER['REQUEST_METHOD']==='POST'){$address=trim($_POST['address']??'');$phone=trim($_POST['phone']??'');$payment=$_POST['payment']??'Transfer Bank';if(strlen($address)<10||strlen($phone)<8)$error='Isi alamat lengkap dan nomor telepon yang valid.';elseif(!in_array($payment,['Transfer Bank','COD'],true))$error='Metode pembayaran tidak valid.';else{
 $number=generateOrderNumber();
 if($conn){$conn->begin_transaction();try{$uid=(int)$_SESSION['user_id'];$stmt=$conn->prepare("INSERT INTO orders (order_number,user_id,total_amount,status,shipping_address,payment_method) VALUES (?, ?, ?, 'pending', ?, ?)");$stmt->bind_param('sidss',$number,$uid,$total,$address,$payment);if(!$stmt->execute())throw new Exception('Gagal menyimpan pesanan.');$orderId=$conn->insert_id;$stmt->close();foreach($items as $p){$pid=(int)$p['id'];$qty=(int)$p['quantity'];$price=(float)$p['price'];$name=$p['name'];$up=$conn->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");$up->bind_param('iii',$qty,$pid,$qty);$up->execute();if($up->affected_rows!==1)throw new Exception('Stok produk berubah. Silakan ulangi checkout.');$up->close();$sold=$conn->prepare("UPDATE products SET status='sold' WHERE id=? AND stock=0");$sold->bind_param('i',$pid);$sold->execute();$sold->close();$it=$conn->prepare('INSERT INTO order_items (order_id,product_id,product_name,quantity,price) VALUES (?,?,?,?,?)');$it->bind_param('iisid',$orderId,$pid,$name,$qty,$price);if(!$it->execute())throw new Exception('Gagal menyimpan item pesanan.');$it->close();}$conn->commit();}catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}}
 else {$_SESSION['demo_orders']=$_SESSION['demo_orders']??[];$_SESSION['demo_orders'][]=['id'=>count($_SESSION['demo_orders'])+100,'order_number'=>$number,'user_id'=>$_SESSION['user_id'],'user_name'=>$_SESSION['user_name'],'total_amount'=>$total,'status'=>'pending','shipping_address'=>$address,'payment_method'=>$payment,'created_at'=>date('Y-m-d H:i:s'),'items'=>array_map(fn($p)=>['product_name'=>$p['name'],'quantity'=>$p['quantity'],'price'=>$p['price']],$items)];}
 if(!$error){$_SESSION['cart']=[];setFlash('success','Pesanan berhasil dibuat dengan nomor '.$number.'.');redirect(BASE_URL.'/buyer/orders.php');}}
}
?>
<section class="section"><div class="container"><div class="page-header"><div><h1>Checkout</h1><p class="text-muted">Lengkapi informasi pengiriman.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= sanitize($error) ?></div><?php endif; ?><div class="checkout-layout"><form method="post" class="checkout-form"><div class="card"><h3>Informasi pengiriman</h3><div class="form-group"><label for="address">Alamat lengkap</label><textarea id="address" name="address" class="form-control" required><?= sanitize($address) ?></textarea></div><div class="form-group"><label for="phone">Nomor telepon</label><input id="phone" name="phone" class="form-control" value="<?= sanitize($phone) ?>" required></div><div class="form-group"><label for="payment">Metode pembayaran</label><select id="payment" name="payment" class="form-control"><option <?= $payment==='Transfer Bank'?'selected':'' ?>>Transfer Bank</option><option <?= $payment==='COD'?'selected':'' ?>>COD</option></select></div><button class="btn btn-primary btn-lg btn-block">Buat pesanan · <?= formatRupiah($total) ?></button></div></form><aside class="cart-summary"><h3>Pesananmu</h3><?php foreach($items as $p): ?><div class="cart-summary-row"><span><?= sanitize($p['name']) ?> × <?= $p['quantity'] ?></span><strong><?= formatRupiah($p['subtotal']) ?></strong></div><?php endforeach; ?><div class="cart-summary-row total"><span>Total</span><span><?= formatRupiah($total) ?></span></div></aside></div></div></section>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
